let player_0 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let least_0 = 0u32; let most_0 = 13u32; let chosen_0: u32 = cantrip_mechanics::choose::number(g, player_0, asker.source, least_0, most_0, "Choose a number")?;
